do $func$
begin
  if not exists (
    select 1
    from pg_roles
    where rolname = 'cli_login_postgres'
  )
  then
    create role cli_login_postgres noinherit login noreplication;
  end if;
  grant postgres to cli_login_postgres;
  set role postgres;
  execute format(
    $$alter role cli_login_postgres with password 'SCRAM-SHA-256$4096:6qXS6iiPm0oAiwOmq5NcaQ==$/beD59haPa4FL8xfca9mpbvhhpJUWjFuwlqRkuMeibs=:YL06V5jDaxxQXBQvEtYMFj+cpApC7RcUETvsQ3kqYcc=' valid until %L$$,
    now() + interval '300 second'
  );
end
$func$ language plpgsql

